const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const defaults={deviceName:'나의 Windows PC',provider:'webdav',server:'https://nas.example.com/webdav',username:'kayman-demo',remoteFolder:'/RyuSync/saves',ryujinxPath:'C:\\Users\\Kayman\\AppData\\Roaming\\Ryujinx',interval:'300',discover:true,autoSync:true,games:[true,true,true,true]};
let saved;try{saved={...defaults,...JSON.parse(localStorage.getItem('ryusync-preview')||'{}')}}catch{saved={...defaults}}
let provider=saved.provider, timer, logs=[];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function record(message){logs.unshift({message,time:new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})});$('#history-list').replaceChildren(...logs.map(x=>{let row=document.createElement('div');row.className='history-row';let label=document.createElement('span');label.textContent=x.message;let time=document.createElement('small');time.textContent=x.time;row.append(label,time);return row}))}
const fields={deviceName:'#device-name',server:'#server',username:'#username',remoteFolder:'#remote-folder',ryujinxPath:'#ryujinx-path',interval:'#interval'};
function selectProvider(name){provider=name;$$('[data-provider]').forEach(b=>{let selected=b.dataset.provider===name;b.classList.toggle('chosen',selected);b.setAttribute('aria-checked',String(selected))});$('#webdav-form').hidden=name!=='webdav';$('#drive-form').hidden=name!=='drive'}
function restore(){for(const [key,selector] of Object.entries(fields))$(selector).value=saved[key]??defaults[key];selectProvider(saved.provider);$$('[data-setting]').forEach(b=>{let on=!!saved[b.dataset.setting];b.classList.toggle('on',on);b.setAttribute('aria-checked',String(on))});$$('.game-select').forEach((b,i)=>b.checked=saved.games[i]??true);$('#save-status').textContent='변경한 설정은 이 브라우저에 저장됩니다.';$('#password').value='';updateCount()}
function dirty(){$('#save-status').textContent='저장하지 않은 변경 사항이 있어요.'}
$$('[data-provider]').forEach(b=>b.onclick=()=>{selectProvider(b.dataset.provider);dirty()});$$('[data-setting]').forEach(b=>b.onclick=()=>{const on=!b.classList.contains('on');b.classList.toggle('on',on);b.setAttribute('aria-checked',String(on));dirty()});$$('input,select').forEach(e=>e.addEventListener('input',dirty));
$('#show-password').onclick=()=>{const hidden=$('#password').type==='password';$('#password').type=hidden?'text':'password';$('#show-password').textContent=hidden?'숨김':'표시';$('#show-password').setAttribute('aria-label',hidden?'비밀번호 숨기기':'비밀번호 표시')};
function save(){if(!$('#device-name').value.trim()){toast('기기 이름을 입력해 주세요.');$('#device-name').focus();return}let state={provider,games:$$('.game-select').map(b=>b.checked)};for(const [key,selector] of Object.entries(fields))state[key]=$(selector).value;$$('[data-setting]').forEach(b=>state[b.dataset.setting]=b.classList.contains('on'));try{localStorage.setItem('ryusync-preview',JSON.stringify(state));saved=state;$('#password').value='';$('#save-status').textContent='설정을 이 브라우저에 저장했어요.';toast('초안 설정을 저장했어요. 비밀번호는 저장하지 않습니다.');record('초안 설정 저장');updateCount()}catch{toast('브라우저 저장소에 접근할 수 없어요.')}}
$('#save').onclick=save;$('#save-games').onclick=save;$('#reset').onclick=()=>{restore();toast('마지막으로 저장한 설정으로 되돌렸어요.')};
function showView(name){$$('.view').forEach(v=>v.hidden=v.id!==`${name}-view`);$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const titles={settings:['설정','어느 기기에서든, 마지막으로 플레이한 곳부터.'],games:['내 게임','자동으로 찾은 세이브를 확인하고 동기화할 게임을 선택하세요.'],overview:['대시보드','당신의 다음 플레이를 위한 준비 상태를 확인하세요.'],history:['동기화 기록','미리보기에서 실행한 작업을 확인하세요.']};$('#page-title').textContent=titles[name][0];$('#crumb').textContent=titles[name][0];$('#page-subtitle').textContent=titles[name][1];window.scrollTo({top:0,behavior:'smooth'})}
$$('nav button').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();showView('settings')};$('#open-games').onclick=()=>showView('games');
$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(t=>{t.classList.toggle('selected',t===b);t.setAttribute('aria-selected',String(t===b))});document.getElementById(b.dataset.tab).scrollIntoView({behavior:'smooth',block:'start'})});
const delay=ms=>new Promise(r=>setTimeout(r,ms));
$('#test-connection').onclick=async()=>{const b=$('#test-connection');try{const u=new URL($('#server').value);if(u.protocol!=='https:'&&u.protocol!=='http:')throw Error()}catch{toast('http:// 또는 https://로 시작하는 주소를 입력해 주세요.');$('#server').focus();return}b.disabled=true;b.textContent='테스트 중…';$('#connection-status').textContent='연결 과정을 시뮬레이션하고 있어요…';await delay(1100);$('#connection-status').textContent='✓ 데모 테스트 완료 · 실제 서버 연결 없음';$('#connection-status').style.color='#3b8066';b.textContent='다시 테스트';b.disabled=false;record('WebDAV 연결 테스트 시뮬레이션 완료');toast('연결 흐름을 미리 확인했어요. 실제 요청은 전송하지 않았습니다.')};
$('#google-connect').onclick=async()=>{const b=$('#google-connect');b.disabled=true;b.textContent='연결 화면 준비 중…';await delay(700);b.disabled=false;b.textContent='Google 계정 다시 연결 · 데모';$('#google-status').textContent='연결 완료 상태 예시 · 실제 Google 계정 접근 없음';record('Google Drive 연결 시뮬레이션 완료');toast('Google Drive 연결 완료 화면의 예시입니다.')};
$('#scan').onclick=async()=>{const b=$('#scan');if(!$('#ryujinx-path').value.trim()){toast('데이터 폴더 경로를 입력해 주세요.');return}b.disabled=true;b.textContent='탐색 중…';$('#scan-summary').textContent='게임과 세이브 정보를 확인하고 있어요…';await delay(950);$('#scan-summary').textContent='게임 4개와 프로필 1개를 찾았어요';b.textContent='다시 탐색';b.disabled=false;record('자동 탐색 시뮬레이션 · 예시 게임 4개');toast('탐색 예시를 불러왔어요. 실제 로컬 파일은 읽지 않습니다.')};
const games=[{name:'젤다의 전설 티어스 오브 더 킹덤',id:'0100F2C0115B6000',path:'0000000000000003',symbol:'✦',color:'#718469'},{name:'젤다의 전설 브레스 오브 더 와일드',id:'01007EF00011E000',path:'0000000000000007',symbol:'❋',color:'#86a49b'},{name:'슈퍼 마리오 오디세이',id:'0100000000010000',path:'0000000000000009',symbol:'M',color:'#c77b6f'},{name:'포켓몬스터 바이올렛',id:'01008F6008C5E000',path:'000000000000000b',symbol:'✧',color:'#9a8aac'}];
$('#games-list').innerHTML=games.map((g,i)=>`<label class="game-row" data-search="${g.name.toLowerCase()} ${g.id.toLowerCase()}"><span class="game-art" style="--art:${g.color}">${g.symbol}</span><span class="game-description"><h3>${g.name}</h3><small>${g.id}</small><p>예시 경로 · bis/user/save/${g.path}/0</p></span><span class="pill success">자동 연결 · 예시</span><input class="game-select" type="checkbox" checked aria-label="${g.name} 동기화 선택"></label>`).join('');
function updateCount(){const n=$$('.game-select').filter(x=>x.checked).length;$('#chosen-count').textContent=n}
$$('.game-select').forEach(x=>x.onchange=()=>{dirty();updateCount()});$('#game-search').oninput=()=>{const q=$('#game-search').value.toLowerCase();$$('.game-row').forEach(r=>r.hidden=!r.dataset.search.includes(q))};
$('#demo-sync').onclick=async()=>{let b=$('#demo-sync');b.disabled=true;b.textContent='변경 사항 확인 중…';await delay(1100);b.disabled=false;b.textContent='동기화 시뮬레이션';record('동기화 시뮬레이션 완료 · 실제 전송 없음');toast('동기화 흐름 확인 완료. 실제 세이브 전송은 없습니다.')};
restore();
